   472  /**
   473   * vips_matrixload:
   474   * @filename: file to load
   475   * @out: (out): output image
   476   * @...: %NULL-terminated list of optional named arguments
   477   *
   478   * Reads a matrix from a file.
   479   *
   480   * Matrix files have a simple format that's supposed to be easy to create with
   481   * a text editor or a spreadsheet.
   482   *
   483   * The first line has four numbers for width, height, scale and
   484   * offset (scale and offset may be omitted, in which case they default to 1.0
   485   * and 0.0). Scale must be non-zero. Width and height must be positive
   486   * integers. The numbers are separated by any mixture of spaces, commas,
   487   * tabs and quotation marks ("). The scale and offset fields may be
   488   * floating-point, and must use '.'
   489   * as a decimal separator.
   490   *
   491   * Subsequent lines each hold one row of matrix data, with numbers again
   492   * separated by any mixture of spaces, commas,
   493   * tabs and quotation marks ("). The numbers may be floating-point, and must
   494   * use '.'
   495   * as a decimal separator.
   496   *
   497   * Extra characters at the ends of lines or at the end of the file are
   498   * ignored.
   499   *
   500   * See also: vips_matrixload().
   501   *
   502   * Returns: 0 on success, -1 on error.
   503   */
   504  int
   505  vips_matrixload( const char *filename, VipsImage **out, ... )
   506  {
   507          va_list ap;
   508          int result;
   509
   510          va_start( ap, out );
   511          result = vips_call_split( "matrixload", ap, filename, out );
   512          va_end( ap );
   513
   514          return( result );
   515  }
